<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<ul>			<a href="{pigcms{:U('Recruit/course_list')}">视频列表</a>|			<a href="{pigcms{:U('Recruit/course_commend')}" class="on">评论列表</a>|			<a href="{pigcms{:U('Recruit/course_category')}">分类列表</a>		</ul>	</div>    <table class="search_table" width="100%">        <tr>            <td>                <form action="{pigcms{:U('Recruit/course_commend')}" method="get">                    <input type="hidden" name="c" value="Recruit"/>                    <input type="hidden" name="a" value="course_commend"/>                    筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                    <select name="type">                        <option value="title" <if condition="$_GET['type'] eq 'title'">selected="selected"</if>>视频标题</option>                        <option value="nickname" <if condition="$_GET['type'] eq 'nickname'">selected="selected"</if>>用户昵称</option>                    </select>                    <input type="submit" value="查询" class="button"/>                </form>            </td>        </tr>    </table>	<form name="myform" id="myform" action="" method="post">		<div class="table-list">			<table width="100%" cellspacing="0">				<colgroup>					<col/>					<col/>					<col/>					<col/>					<col/>					<col  align="center"/>				</colgroup>				<thead>					<tr>						<th>编号</th>						<th>视频标题</th>						<th>评论内容 </th>						<th>用户昵称</th>						<th>评论时间</th>						<th>操作</th>					</tr>				</thead>				<tbody>					<if condition="$list">						<volist name="list" id="vo">							<tr>								<td>{pigcms{$vo.cl_Id}</td>								<td>{pigcms{$vo.title}</td>								<td>{pigcms{$vo.cl_CommentContent}</td>                                <td>{pigcms{$vo.nickname}</td>                                <td>{pigcms{$vo.cl_CommentTime|date='Y-m-d H:i:s',###}</td>								<td>									<a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.cl_Id}" url="{pigcms{:U('course_commend_del')}">删除</a>							  	</td>							</tr>						</volist>						<tr><td class="textcenter pagebar" colspan="10">{pigcms{$pagebar}</td></tr>					<else/>						<tr><td class="textcenter red" colspan="10">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><include file="Public:footer"/>